inline constexpr std::string_view kTemporalShader = R"delss(#version 300 es
// DeLSS pass: temporal
// DeLSS shared prelude. Inlined into every pass by tools/gen.py.
//
// Input contract (mirrors DLSS): every pass sees the original color frame and
// optional G-buffer channels. A pass that needs a channel checks its uHas*
// flag and falls back gracefully when the host did not provide it.
precision highp float;
precision highp int;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D uSrc;      // output of the previous pass (the frame on pass 0)
uniform sampler2D uColor;    // original engine color, linear-ish sRGB, RGBA8
uniform sampler2D uDepth;    // r = linear depth in [0,1], 0 = near
uniform sampler2D uNormal;   // rgb = view-space normal * 0.5 + 0.5
uniform sampler2D uMotion;   // rg = screen-space motion in UV units (cur - prev)
uniform sampler2D uHistory;  // previous final output of this chain
uniform bool uHasDepth;
uniform bool uHasNormal;
uniform bool uHasMotion;
uniform bool uHasHistory;
uniform vec2 uResolution;    // output size in pixels
uniform int uFrame;          // frame counter, only used by passes that want noise
uniform float uIntensity;    // 0 = bypass, 1 = full effect (artist control)

const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

float luma(vec3 c) { return dot(c, LUMA); }

vec2 texel() { return 1.0 / uResolution; }

vec4 src(vec2 uv) { return texture(uSrc, uv); }

// Classic 8x8 Bayer threshold in [0,1). Anchored to integer screen cells, so it
// never crawls when the camera is still and never shimmers between frames.
float bayer8(ivec2 p) {
  p &= 7;
  int x = p.x;
  int y = p.y ^ p.x;
  int v = ((y & 1) << 5) | ((x & 1) << 4) | ((y & 2) << 2) | ((x & 2) << 1) | ((y & 4) >> 1) |
          ((x & 4) >> 2);
  return (float(v) + 0.5) / 64.0;
}

// The PlayStation GPU's 4x4 dither table, in 8-bit color steps.
float ps1Dither(ivec2 p) {
  const float m[16] = float[16](-4.0, 0.0, -3.0, 1.0, 2.0, -2.0, 3.0, -1.0, -3.0, 1.0, -4.0, 0.0,
                                3.0, -1.0, 2.0, -2.0);
  p &= 3;
  return m[p.y * 4 + p.x];
}

// Integer hash (no sin()): bit-exact across GPUs, which keeps goldens stable.
float hash12(uvec2 p) {
  uvec3 v = uvec3(p, 0x9E37u) * uvec3(1597334673u, 3812015801u, 2798796415u);
  uint n = (v.x ^ v.y ^ v.z) * 1597334673u;
  return float(n >> 8) / 16777216.0;
}

vec3 srgbToLinear(vec3 c) { return pow(max(c, 0.0), vec3(2.2)); }
vec3 linearToSrgb(vec3 c) { return pow(max(c, 0.0), vec3(1.0 / 2.2)); }

// OKLab: perceptual color space; nearest-palette search in it looks much better
// than plain RGB distance (no muddy greens for skin tones).
vec3 toOklab(vec3 srgb) {
  vec3 c = srgbToLinear(srgb);
  vec3 lms = mat3(0.4122214708, 0.2119034982, 0.0883024619, 0.5363325363, 0.6806995451,
                  0.2817188376, 0.0514459929, 0.1073969566, 0.6299787005) *
             c;
  lms = pow(max(lms, 0.0), vec3(1.0 / 3.0));
  return mat3(0.2104542553, 1.9779984951, 0.0259040371, 0.7936177850, -2.4285922050,
              0.7827717662, -0.0040720468, 0.4505937099, -0.8086757660) *
         lms;
}

// Final blend shared by every pass: the intensity slider is a straight mix
// against the pass input, so 0 is an exact bypass.
vec4 delssOut(vec3 styled) {
  vec3 base = src(vUv).rgb;
  return vec4(mix(base, styled, clamp(uIntensity, 0.0, 1.0)), 1.0);
}

// temporal: anti-flicker for quantized styles, the DeLSS counterpart of TAA.
//
// Quantizing (palette, cel bands, dither) is a discontinuous function: noise of
// one 8-bit step in the input can flip a pixel between two palette colors every
// frame. We reproject last frame's *output* with motion vectors and keep it
// when it is still a plausible answer, i.e. it lies inside the color box of the
// current frame's neighborhood, sampled one u_cell apart so that for pixel art
// the test spans neighboring fat pixels rather than the inside of one. Keeping a previous palette color is
// lossless (it is still a palette color), so unlike TAA this adds no blur;
// the neighborhood test stops ghosting on disocclusions.
uniform float u_stability;  // probability of keeping plausible history; 1 - u_stability of
                            // pixels refresh each frame so frozen patterns still converge
uniform float u_tolerance;  // how far outside the box history may be
uniform float u_cell;       // decision block in pixels; match pixelate's pixel size

void main() {
  vec3 cur = src(vUv).rgb;
  if (!uHasHistory) {
    fragColor = vec4(cur, 1.0);
    return;
  }
  vec2 motion = uHasMotion ? texture(uMotion, vUv).rg : vec2(0.0);
  vec2 prevUv = vUv - motion;
  if (any(lessThan(prevUv, vec2(0.0))) || any(greaterThan(prevUv, vec2(1.0)))) {
    fragColor = vec4(cur, 1.0);
    return;
  }
  vec3 hist = texture(uHistory, prevUv).rgb;
  vec3 lo = cur;
  vec3 hi = cur;
  float cell = max(1.0, floor(u_cell + 0.5));
  vec2 t = texel() * cell;
  for (int j = -1; j <= 1; ++j) {
    for (int i = -1; i <= 1; ++i) {
      vec3 n = src(vUv + vec2(i, j) * t).rgb;
      lo = min(lo, n);
      hi = max(hi, n);
    }
  }
  vec3 tol = vec3(u_tolerance);
  bool plausible = all(greaterThanEqual(hist, lo - tol)) && all(lessThanEqual(hist, hi + tol));
  // Hard select instead of a blend: blending two palette colors would create an
  // off-palette color and smear pixel art.
  // One refresh decision per block, so a fat pixel never splits in two.
  uvec2 block = uvec2(floor(gl_FragCoord.xy / cell));
  float roll = hash12(block ^ uvec2(uint(uFrame) * 2654435761u));
  float keep = plausible && roll < u_stability ? 1.0 : 0.0;
  fragColor = vec4(mix(cur, hist, keep * clamp(uIntensity, 0.0, 1.0)), 1.0);
}
)delss";

inline constexpr std::string_view kVhsShader = R"delss(#version 300 es
// DeLSS pass: vhs
// DeLSS shared prelude. Inlined into every pass by tools/gen.py.
//
// Input contract (mirrors DLSS): every pass sees the original color frame and
// optional G-buffer channels. A pass that needs a channel checks its uHas*
// flag and falls back gracefully when the host did not provide it.
precision highp float;
precision highp int;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D uSrc;      // output of the previous pass (the frame on pass 0)
uniform sampler2D uColor;    // original engine color, linear-ish sRGB, RGBA8
uniform sampler2D uDepth;    // r = linear depth in [0,1], 0 = near
uniform sampler2D uNormal;   // rgb = view-space normal * 0.5 + 0.5
uniform sampler2D uMotion;   // rg = screen-space motion in UV units (cur - prev)
uniform sampler2D uHistory;  // previous final output of this chain
uniform bool uHasDepth;
uniform bool uHasNormal;
uniform bool uHasMotion;
uniform bool uHasHistory;
uniform vec2 uResolution;    // output size in pixels
uniform int uFrame;          // frame counter, only used by passes that want noise
uniform float uIntensity;    // 0 = bypass, 1 = full effect (artist control)

const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

float luma(vec3 c) { return dot(c, LUMA); }

vec2 texel() { return 1.0 / uResolution; }

vec4 src(vec2 uv) { return texture(uSrc, uv); }

// Classic 8x8 Bayer threshold in [0,1). Anchored to integer screen cells, so it
// never crawls when the camera is still and never shimmers between frames.
float bayer8(ivec2 p) {
  p &= 7;
  int x = p.x;
  int y = p.y ^ p.x;
  int v = ((y & 1) << 5) | ((x & 1) << 4) | ((y & 2) << 2) | ((x & 2) << 1) | ((y & 4) >> 1) |
          ((x & 4) >> 2);
  return (float(v) + 0.5) / 64.0;
}

// The PlayStation GPU's 4x4 dither table, in 8-bit color steps.
float ps1Dither(ivec2 p) {
  const float m[16] = float[16](-4.0, 0.0, -3.0, 1.0, 2.0, -2.0, 3.0, -1.0, -3.0, 1.0, -4.0, 0.0,
                                3.0, -1.0, 2.0, -2.0);
  p &= 3;
  return m[p.y * 4 + p.x];
}

// Integer hash (no sin()): bit-exact across GPUs, which keeps goldens stable.
float hash12(uvec2 p) {
  uvec3 v = uvec3(p, 0x9E37u) * uvec3(1597334673u, 3812015801u, 2798796415u);
  uint n = (v.x ^ v.y ^ v.z) * 1597334673u;
  return float(n >> 8) / 16777216.0;
}

vec3 srgbToLinear(vec3 c) { return pow(max(c, 0.0), vec3(2.2)); }
vec3 linearToSrgb(vec3 c) { return pow(max(c, 0.0), vec3(1.0 / 2.2)); }

// OKLab: perceptual color space; nearest-palette search in it looks much better
// than plain RGB distance (no muddy greens for skin tones).
vec3 toOklab(vec3 srgb) {
  vec3 c = srgbToLinear(srgb);
  vec3 lms = mat3(0.4122214708, 0.2119034982, 0.0883024619, 0.5363325363, 0.6806995451,
                  0.2817188376, 0.0514459929, 0.1073969566, 0.6299787005) *
             c;
  lms = pow(max(lms, 0.0), vec3(1.0 / 3.0));
  return mat3(0.2104542553, 1.9779984951, 0.0259040371, 0.7936177850, -2.4285922050,
              0.7827717662, -0.0040720468, 0.4505937099, -0.8086757660) *
         lms;
}

// Final blend shared by every pass: the intensity slider is a straight mix
// against the pass input, so 0 is an exact bypass.
vec4 delssOut(vec3 styled) {
  vec3 base = src(vUv).rgb;
  return vec4(mix(base, styled, clamp(uIntensity, 0.0, 1.0)), 1.0);
}

// vhs: analog tape. Chroma is stored at a fraction of the luma bandwidth on
// VHS, so color smears horizontally while brightness stays sharp. Optional
// tracking noise is the one place DeLSS uses time on purpose; set u_noise to 0
// for a perfectly static result.
uniform float u_chromaBlur;   // horizontal chroma smear in pixels
uniform float u_chromaShift;  // red/blue misregistration in pixels
uniform float u_noise;        // tracking noise and line jitter, 0 = off
uniform float u_sharpen;      // VHS decks over-sharpen luma (ringing)

vec3 rgb2yiq(vec3 c) {
  return mat3(0.299, 0.596, 0.211, 0.587, -0.274, -0.523, 0.114, -0.322, 0.312) * c;
}
vec3 yiq2rgb(vec3 c) {
  return mat3(1.0, 1.0, 1.0, 0.956, -0.272, -1.106, 0.621, -0.647, 1.703) * c;
}

void main() {
  vec2 t = texel();
  float row = floor(gl_FragCoord.y);
  // Per-line jitter, re-rolled every 4 frames so it reads as tape wobble, not sparkle.
  uint epoch = uint(uFrame / 4);
  float jitter = (hash12(uvec2(uint(row), epoch)) - 0.5) * u_noise * 3.0;
  vec2 uv = vUv + vec2(jitter * t.x, 0.0);

  float y = rgb2yiq(src(uv).rgb).x;
  float yl = rgb2yiq(src(uv - vec2(t.x, 0.0)).rgb).x;
  float yr = rgb2yiq(src(uv + vec2(t.x, 0.0)).rgb).x;
  y += (2.0 * y - yl - yr) * u_sharpen;

  vec2 iq = vec2(0.0);
  float wsum = 0.0;
  for (int i = -8; i <= 8; ++i) {
    float x = float(i) * max(u_chromaBlur, 0.0) / 8.0;
    float w = exp(-float(i * i) / 32.0);
    iq += rgb2yiq(src(uv + vec2((x + u_chromaShift) * t.x, 0.0)).rgb).yz * w;
    wsum += w;
  }
  iq /= wsum;
  vec3 c = yiq2rgb(vec3(y, iq));

  // Bottom-of-frame head-switching band plus sparse dropout streaks.
  float band = smoothstep(0.035, 0.0, vUv.y) * u_noise;
  float drop = step(0.9985, hash12(uvec2(uint(row), epoch * 7u + 3u))) * u_noise;
  c = mix(c, vec3(hash12(uvec2(gl_FragCoord.xy) + epoch)), max(band, drop));
  fragColor = delssOut(clamp(c, 0.0, 1.0));
}
)delss";

